// PROJECT BLACKOUT V0.1 — TRAINING ANNEX
// Visual structures and physical colliders are generated by the same helpers.
// No REDLINE modules or account systems are imported.
export function buildAnnex(THREE, scene) {
  const colliders = [], meshes = [];
  const group = new THREE.Group();
  scene.add(group);
  scene.background = new THREE.Color(0x070d15);
  scene.fog = new THREE.Fog(0x080e16, 35, 78);
  scene.add(new THREE.HemisphereLight(0x93b9d9, 0x1b202b, 1.45));
  const key = new THREE.DirectionalLight(0xd0e7ff, 1.12);
  key.position.set(-15, 18, -12); scene.add(key);

  function noiseTexture(base) {
    const cv = document.createElement("canvas");
    cv.width = 128; cv.height = 128;
    const c = cv.getContext("2d");
    c.fillStyle = base; c.fillRect(0, 0, 128, 128);
    let seed = 14498;
    function rand() { seed = (Math.imul(seed, 1664525) + 1013904223) | 0; return (seed >>> 0) / 4294967296; }
    for (let i = 0; i < 2350; i++) {
      const x = rand() * 128, y = rand() * 128;
      const v = rand() > .55 ? 255 : 5;
      c.fillStyle = `rgba(${v},${v},${v},${.015 + rand() * .07})`;
      c.fillRect(x, y, 1 + rand() * 6, .5 + rand() * 2.5);
    }
    c.strokeStyle = "rgba(0,0,0,.16)";
    for(let x = 0; x <= 128; x += 32) {
      c.beginPath(); c.moveTo(x, 0); c.lineTo(x, 128); c.stroke();
    }
    const t = new THREE.CanvasTexture(cv);
    t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 4;
    return t;
  }
  const concrete = new THREE.MeshStandardMaterial({ map: noiseTexture("#71808b"), color: 0x9ba7ae, roughness: 1 });
  const darkPanel = new THREE.MeshStandardMaterial({ map: noiseTexture("#2e3949"), color: 0x8c9cad, metalness: .24, roughness: .77 });
  const metal = new THREE.MeshStandardMaterial({color:0x657385,metalness:.76,roughness:.39});
  const floor = new THREE.MeshStandardMaterial({map:noiseTexture("#393e48"),color:0xa5b3c6,roughness:.97});
  const rubber = new THREE.MeshStandardMaterial({map:noiseTexture("#313840"),color:0x81909d,roughness:1});
  const ceiling = new THREE.MeshStandardMaterial({color:0x222b37,roughness:.95,side:THREE.DoubleSide});
  const orange = new THREE.MeshStandardMaterial({color:0xffa449,emissive:0x713810,emissiveIntensity:.4,metalness:.2,roughness:.56});
  const cyan = new THREE.MeshStandardMaterial({color:0x5de2e0,emissive:0x17d4d0,emissiveIntensity:1.1});
  const black = new THREE.MeshStandardMaterial({color:0x111820,roughness:.76});
  const emissive = new THREE.MeshBasicMaterial({color:0xdae9ef});
  const glass = new THREE.MeshStandardMaterial({color:0x829eae,transparent:true,opacity:.27,metalness:.32,roughness:.18,depthWrite:false,side:THREE.DoubleSide});
  function box(x,y,z,w,h,d,mat,solid=false,tag="structure") {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);
    mesh.position.set(x,y,z);
    group.add(mesh);
    meshes.push(mesh);
    if(solid)colliders.push({minX:x-w/2,maxX:x+w/2,minZ:z-d/2,maxZ:z+d/2,minY:y-h/2,maxY:y+h/2,tag});
    return mesh;
  }
  function wallX(x1,x2,z,mat=concrete) { if(x2-x1>0.005)box((x1+x2)/2,2.42,z,x2-x1,4.84,.36,mat,true,"wall"); }
  function wallZ(x,z1,z2,mat=concrete) { if(z2-z1>0.005)box(x,2.42,(z1+z2)/2,.36,4.84,z2-z1,mat,true,"wall"); }
  // Fully enclosed playable rooms, including continuous perimeter.
  wallX(-24,24,-18);wallX(-24,24,18);
  wallZ(-24,-18,18);wallZ(24,-18,18);
  // West spawn / movement split: open four-metre doorway.
  wallX(-24,-17,1,darkPanel);wallX(-13,-7,1,darkPanel);
  // West rooms connect to central corridor through two real doorways.
  wallZ(-7,-18,-11);wallZ(-7,-5.8,7.8);wallZ(-7,13,18);
  // Range entry, with a wide opening on the south side.
  wallZ(6,-18,11);wallZ(6,15,18);
  // Mid-corridor S bends: cannot walk straight through solid geometry.
  wallX(-7,2,-1,darkPanel);wallX(-1,6,7,darkPanel);

  // Door frames and overhead headers, height-clear above standing player.
  function portalX(x1,x2,z,heading) {
    for (const x of [x1,x2])box(x,1.23,z,.18,2.46,.58,metal,false);
    box((x1+x2)/2,2.59,z,x2-x1+.35,.28,.60,metal,true,"door-header");
    box((x1+x2)/2,2.85,z,x2-x1+.2,.11,.65,heading?orange:cyan,false);
  }
  function portalZ(x,z1,z2,heading) {
    for (const z of [z1,z2])box(x,1.23,z,.58,2.46,.18,metal,false);
    box(x,2.59,(z1+z2)/2,.60,.28,z2-z1+.35,metal,true,"door-header");
    box(x,2.85,(z1+z2)/2,.65,.11,z2-z1+.2,heading?orange:cyan,false);
  }
  portalX(-17,-13,1,true);portalZ(-7,-11,-5.8,false);
  portalZ(-7,7.8,13,false);portalZ(6,11,15,true);

  // Flooring: base slab and distinct material treatment in each zone.
  box(0,-.145,0,48,.29,36,floor,true,"floor-base");
  box(-15.5,-.04,-8.5,16.6,.07,18.5,rubber);
  box(-15.5,-.04,9.5,16.6,.07,16.5,rubber);
  box(-.5,-.04,0,12.2,.07,35.6,darkPanel);
  box(15,-.04,0,17.6,.07,35.6,rubber);
  // Ceiling is visible and solid; no exterior shortcuts or missing roof.
  box(0,4.95,0,48,.22,36,ceiling,true,"ceiling");
  // Wall skirting and mechanical services.
  for (const z of [-17.65,17.65])box(0,.22,z,47.5,.36,.18,metal);
  for (const x of [-23.65,23.65])box(x,.22,0,.18,.36,35.5,metal);
  for (const x of [-21,-13,-5,3,11,19]) {
    for(const z of [-14,-5,4,13]){
      box(x,4.79,z,3.4,.09,.11,metal);
    }
  }
  function light(x,z,tint=0x9bdaf0) {
    box(x,4.74,z,2.55,.13,.45,black);
    const glassLight = new THREE.MeshBasicMaterial({color:tint});
    box(x,4.66,z,2.27,.06,.24,glassLight);
  }
  for(const [x,z] of [[-16,-13],[-16,-5],[-16,6],[-16,14],[-.6,-13],[-.6,-5],[-.6,3],[-.6,12],[14,-13],[14,-4],[14,5],[14,14]])light(x,z);
  const lights=[[ -16, 8, 0xa8dbf7, 1.7],[-.5,0,0xb3eaff,1.65],[14,0,0xffc58d,1.4]];
  for(const [x,z,color,intensity] of lights){
    const p=new THREE.PointLight(color,intensity,23,2);
    p.position.set(x,4.2,z);scene.add(p);
  }
  // Spawn / equipment bay, intentionally placed away from exits.
  box(-21,.55,-13,1.45,1.10,3.4,metal,true,"locker");
  for(const z of [-15,-12.6,-10.2]) {
    box(-21.03,1.1,z,.08,1.5,.04,black);
    box(-20.94,1.6,z,.08,.045,.20,orange);
  }
  box(-19,.52,-2.3,4.2,1.02,1.35,darkPanel,true,"equipment-table");
  box(-19,1.08,-2.3,3.9,.09,1.16,metal);
  box(-15.5,.52,-15.6,1.15,1.05,1.45,black,true,"storage-case");
  box(-13.8,.34,-15.6,1.1,.68,1.35,black,true,"storage-case");

  // Corridor: physically blocking low cover / duct. No empty props.
  box(-3.5,.52,-12.6,2.65,1.04,.95,metal,true,"supply-cover");
  box(.7,.64,2.9,1.35,1.28,2,black,true,"junction-cabinet");
  box(.01,1.45,2.9,.05,1.2,1.15,cyan); // cabinet display
  box(3.9,.35,10.1,1.8,.7,1.25,metal,true,"supply-cover");
  box(-3.7,2.68,11.9,3.1,.66,.6,darkPanel,true,"overhead-service-duct");
  // Defensive sightline glass: solid pane, matches visible render.
  box(5.68,1.45,-8,.065,2.35,5.1,glass,true,"reinforced-glass");

  // Movement room: graded ramp and accessible elevated inspection platform.
  // FloorAt() uses these exact extents and heights (same geometry).
  const rx1=-21.5,rx2=-13.5,rz1=5,rz2=11,rise=.78;
  const verts=new Float32Array([
    rx1,0,rz1, rx2,0,rz1, rx1,rise,rz2,
    rx2,0,rz1, rx2,rise,rz2, rx1,rise,rz2,
    rx1,-.06,rz1, rx2,-.06,rz1, rx1,0,rz1,
    rx2,-.06,rz1, rx2,0,rz1, rx1,0,rz1
  ]);
  const geo=new THREE.BufferGeometry();
  geo.setAttribute("position",new THREE.BufferAttribute(verts,3));
  geo.computeVertexNormals();
  const ramp=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:0x657b90,roughness:.87,side:THREE.DoubleSide}));
  group.add(ramp);
  box(-17.5,rise-.10,13,8,.2,4,metal); // raised platform
  // Anti-slip bands, flush with ramp visual; no fake collision steps.
  for(let i=1;i<7;i++){
    const z=rz1+i;
    const y=rise*i/6+.012;
    const strip=box(-17.5,y,z,7.7,.012,.07,orange);
  }
  for(const x of [rx1+.1,rx2-.1]){
    box(x,.45,13,.13,.9,4,metal,true,"platform-rail");
  }
  // Crouch-height duct: stand blocked, crouched player fits underneath.
  box(-11.4,1.81,5.1,2.6,.86,.68,darkPanel,true,"crouch-test-duct");
  // Decorative catwalk rail and reinforced panel.
  box(-22.95,1.7,9,.20,1.70,11,darkPanel);
  box(-21.8,.05,2.8,2,.02,.20,orange);
  box(-17.3,.05,2.8,2,.02,.20,orange);

  // Range: three sight lanes, boxed targets for visual orientation only.
  for(const x of [10.7,15.5,20.3]){
    box(x,.05,12.7,3.1,.09,2.0,darkPanel);
    box(x,.20,11.7,3.4,.25,.13,orange);
    for(const z of [-12,-6.5,-1]){
      const stand=box(x,1.2,z,.14,2.3,.12,metal);
      box(x,1.5,z,.8,.98,.11,black);
      box(x,1.55,z,.34,.34,.12,orange);
      box(x,.23,z,.7,.38,.65,metal,true,"target-base");
    }
  }
  // Range backstop remains a physical visible object.
  box(15,1.8,-16.7,16.7,3.6,.65,darkPanel,true,"range-backstop");
  for(let x=8;x<=23;x+=1.8)box(x,2.1,-16.23,.08,3.2,.14,metal);

  function sign(message,x,y,z,rotation=0,width=3.8) {
    const cv=document.createElement("canvas");
    cv.width=512;cv.height=128;const c=cv.getContext("2d");
    c.fillStyle="#0c1c28";c.fillRect(0,0,512,128);
    c.fillStyle="#3f7889";c.fillRect(0,0,512,8);
    c.font="bold 43px sans-serif";c.textAlign="center";c.textBaseline="middle";
    c.fillStyle="#c7e8f2";c.fillText(message,256,71,480);
    const t=new THREE.CanvasTexture(cv);t.colorSpace=THREE.SRGBColorSpace;
    const m=new THREE.Mesh(new THREE.PlaneGeometry(width,.98),new THREE.MeshBasicMaterial({map:t,side:THREE.DoubleSide}));
    m.position.set(x,y,z);m.rotation.y=rotation;group.add(m);
  }
  sign("01 / EQUIPMENT", -15.8,3.32,-17.77,0,5.0);
  sign("02 / MOBILITY", -16,3.32,17.75,Math.PI,4.8);
  sign("03 / CROSSROUTE", -.7,3.32,17.72,Math.PI,5.2);
  sign("04 / FIRING RANGE", 14.9,3.32,17.74,Math.PI,5.2);

  function floorAt(x,z) {
    if(x>=rx1&&x<=rx2&&z>=rz1&&z<=rz2)
      return rise*(z-rz1)/(rz2-rz1);
    if(x>=rx1&&x<=rx2&&z>rz2&&z<=15)
      return rise;
    return 0;
  }
  const zones=[
    {id:"spawn",name:"EQUIPMENT BAY",test:(x,z)=>x< -7&&z<1},
    {id:"movement",name:"MOBILITY LAB",test:(x,z)=>x< -7&&z>=1},
    {id:"corridor",name:"CROSSROUTE CORRIDOR",test:(x,z)=>x>=-7&&x<6},
    {id:"range",name:"FIRING RANGE",test:(x,z)=>x>=6}
  ];
  function zoneAt(x,z){return zones.find(a=>a.test(x,z))?.name||"ANNEX";}
  return {root:group,colliders,meshes,floorAt,zoneAt,spawn:{x:-15.7,z:-9.6,y:0,yaw:Math.PI/2},
    specifications:{width:48,depth:36,areas:zones.length,solidCount:colliders.length},
    dispose(){for(const m of meshes)m.geometry?.dispose?.();}
  };
}
